(()=>{const o=[];const W=innerWidth;
const m=document.querySelector('meta[name="viewport"]');const vc=m?(m.getAttribute('content')||''):'';
o.push('viewport-fit-cover='+(/viewport-fit\s*=\s*cover/.test(vc)?'ok':'fail'));
const gr=document.querySelector('[data-testid="game-root"]');
const ta=gr?getComputedStyle(gr).touchAction:'';const tab=getComputedStyle(document.body).touchAction;
o.push('touch-action='+(/manipulation|none/.test(ta)||/manipulation|none/.test(tab)?'ok':'fail'));
o.push('no-h-scroll='+(document.documentElement.scrollWidth<=W+1?'ok':'fail'));
let safe=false;try{safe=[...document.styleSheets].some(ss=>{try{return [...ss.cssRules].some(r=>/safe-area-inset/.test(r.cssText));}catch(e){return false;}});}catch(e){}
o.push('safe-area='+(safe?'ok':'fail'));
o.push('pwa-manifest='+(document.querySelector('link[rel="manifest"]')?'ok':'fail'));
o.push('privacy-link='+(document.querySelector('[data-testid="privacy-link"]')?'ok':'fail'));
return o.join('|');})()

(()=>{const o=[];const gr=document.querySelector('[data-testid="game-root"]');
o.push('game-over='+((gr&&gr.getAttribute('data-game-state'))==='game-over'?'ok':'fail'));
const b=document.querySelector('[data-testid="best"]');const bv=b?parseInt((b.textContent||'').replace(/[^0-9]/g,''),10):NaN;
o.push('best-present='+(b?'ok':'fail'));
o.push('best-updated='+(Number.isFinite(bv)&&bv>=2?'ok':'fail'));
const dl=document.querySelector('[data-testid="score-delta"]');
o.push('so-close='+(dl&&(dl.textContent||'').trim().length>0?'ok':'fail'));
o.push('score-card='+(document.querySelector('[data-testid="score-card"]')?'ok':'fail'));
return o.join('|');})()

(()=>{const o=[];const beds=[...document.querySelectorAll('[data-lane-kind="riverbed"]')];
o.push('riverbeds-present='+(beds.length>0?'ok':'fail'));
const ok=beds.length>0&&beds.every(bed=>{const logs=[...bed.querySelectorAll('[data-obstacle-kind="log"]')];
return logs.some(l=>{const x=parseFloat(l.style.left);return Number.isFinite(x)&&Math.abs(x-50)<=32;});});
o.push('every-riverbed-reachable='+(ok?'ok':'fail'));return o.join('|');})()
